question.solution:
class Node:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def list_stats(head):
    count = 0
    best = None
    while head is not None:
        count += 1
        if best is None or head.val > best:
            best = head.val
        head = head.next
    return count, best

def build(values):
    head = None
    for v in reversed(values):
        head = Node(v, head)
    return head

print(list_stats(build([1, 5, 3])))
print(list_stats(None))
print(list_stats(build([-3, -1, -7])))
print(list_stats(build([2, 2, 2])))

